 type Direction = 'ltr' | 'rtl';
 
 /* -------------------------------------------------------------------------------------------------
  * DropdownMenu
  * -----------------------------------------------------------------------------------------------*/
 
 const DROPDOWN_MENU_NAME = 'DropdownMenu';
 
 type ScopedProps<P> = P & { __scopeDropdownMenu?: Scope };
 const [createDropdownMenuContext, createDropdownMenuScope] = createContextScope(
   DROPDOWN_MENU_NAME,
   [createMenuScope],
 );
 const useMenuScope = createMenuScope();
 
 type DropdownMenuContextValue = {
   triggerId: string;
   triggerRef: React.RefObject<HTMLButtonElement | null>;
   contentId: string;
   open: boolean;
   onOpenChange(open: boolean): void;
   onOpenToggle(): void;
   modal: boolean;
 };
 
 const [DropdownMenuProvider, useDropdownMenuContext] =
   createDropdownMenuContext<DropdownMenuContextValue>(DROPDOWN_MENU_NAME);
 
 interface DropdownMenuProps {
   children?: React.ReactNode;
   dir?: Direction;
   open?: boolean;
   defaultOpen?: boolean;
   onOpenChange?(open: boolean): void;
   modal?: boolean;
 }
 
 const DropdownMenu: React.FC<DropdownMenuProps> = (props: ScopedProps<DropdownMenuProps>) => {
   const {
     __scopeDropdownMenu,
     children,
     dir,
     open: openProp,
     defaultOpen,
     onOpenChange,
     modal = true,
   } = props;
   const menuScope = useMenuScope(__scopeDropdownMenu);
   const triggerRef = React.useRef<HTMLButtonElement>(null);
   const [open, setOpen] = useControllableState({
     prop: openProp,
     defaultProp: defaultOpen ?? false,
     onChange: onOpenChange,
     caller: DROPDOWN_MENU_NAME,
   });
 
   return (
     <DropdownMenuProvider
       scope={__scopeDropdownMenu}
       triggerId={useId()}
       triggerRef={triggerRef}
       contentId={useId()}
       open={open}
       onOpenChange={setOpen}
       onOpenToggle={React.useCallback(() => setOpen((prevOpen) => !prevOpen), [setOpen])}
